/* === assets\css\travhub.css === */
/*--------------------------------------------------------------
>>> TABLE OF CONTENTS:
----------------------------------------------------------------
# Utility
# Common
# Animations
# Mobile Nav
# Search Popup
# Page Header
--------------------------------------------------------------*/
:root {
  --travhub-font: "Roboto", serif;
  --travhub-heading-font: "Geologica", serif;
  --travhub-special-font: "Caveat", serif;
  --travhub-text: #555555;
  --travhub-text-rgb: 85, 85, 85;
  --travhub-text2: #757575;
  --travhub-text2-rgb: 117, 117, 117;
  --travhub-base: #1BBC9B;
  --travhub-base-rgb: 27, 188, 155;
  --travhub-primary: #abe6d7;
  --travhub-primary-rgb: 171, 230, 215;
  --travhub-gray: #F0F0F0;
  --travhub-gray-rgb: 240, 240, 240;
  --travhub-gray2: #F1F4FA;
  --travhub-gray2-rgb: 241, 244, 250;
  --travhub-white: #fff;
  --travhub-white-rgb: 255, 255, 255;
  --travhub-black: #292929;
  --travhub-black-rgb: 41, 41, 41;
  --travhub-black2: #343434;
  --travhub-black2-rgb: 52, 52, 52;
  --travhub-black3: #000;
  --travhub-black3-rgb: 0, 0, 0;
  --travhub-border-color: #e5e3e0;
  --travhub-border-color-rgb: 229, 227, 224;
}

/*--------------------------------------------------------------
# Utility
--------------------------------------------------------------*/
.pt-110 {
  padding-top: 110px;

  @media (max-width: 767px){
    padding-top: 70px;
  }
}

.pt-115 {
  padding-top: 115px;

  @media (max-width: 767px){
    padding-top: 75px;
  }
}

.pt-120 {
  padding-top: 120px;

  @media (max-width: 767px){
    padding-top: 80px;
  }
}

.pb-110 {
  padding-bottom: 110px;

  @media (max-width: 767px){
    padding-bottom: 70px;
  }
}

.pb-115 {
  padding-bottom: 115px;

  @media (max-width: 767px){
    padding-bottom: 75px;
  }
}

.pb-120 {
  padding-bottom: 120px;

  @media (max-width: 767px){
    padding-bottom: 80px;
  }
}


/*--------------------------------------------------------------
# Common
--------------------------------------------------------------*/
body {
  font-family: var(--travhub-font);
  color: var(--travhub-text);
  font-size: 16px;
  line-height: 1.875;
  font-weight: 400;
}

body.locked {
  overflow: hidden;
}

a {
  color: var(--travhub-base);
  transition: all 400ms ease;
}

a,
a:hover,
a:focus,
a:visited {
  text-decoration: none;
}

::placeholder {
  color: inherit;
  opacity: 1;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--travhub-heading-font);
  color: var(--travhub-black);
}
@media (max-width: 575px) {
  h1 br,
  h2 br,
  h3 br,
  h4 br,
  h5 br,
  h6 br {
    display: none;
  }
}

@media (max-width: 575px) {
  p br {
    display: none;
  }
}

::placeholder {
  color: inherit;
  opacity: 1;
}

.background-base {
  background-color: var(--travhub-base);
}

.background-gray {
  background-color: var(--travhub-gray);
}

.background-black {
  background-color: var(--travhub-black);
}

.background-black-2 {
  background-color: var(--travhub-black2);
}


.page-wrapper {
  position: relative;
  margin: 0 auto;
  width: 100%;
  min-width: 300px;
  overflow: hidden;
}

.container-fluid,
.container {
  padding-left: 15px;
  padding-right: 15px;
}

@media (min-width: 1200px) {
  .container {
    max-width: 1200px;
  }
}

@media (min-width: 1400px) {
  .container {
    max-width: 1350px;
  }
}
.row {
  --bs-gutter-x: 30px;
}

.gutter-y-10 {
  --bs-gutter-y: 10px;
}

.gutter-y-15 {
  --bs-gutter-y: 15px;
}

.gutter-y-20 {
  --bs-gutter-y: 20px;
}

.gutter-y-30 {
  --bs-gutter-y: 30px;
}

.gutter-y-60 {
  --bs-gutter-y: 60px;
}

.travhub-btn {
  display: inline-block;
  vertical-align: middle;
  -webkit-appearance: none;
  border: none;
  outline: none !important;
  font-family: var(--travhub-font);
  background-color: var(--travhub-base);
  color: var(--travhub-white);
  font-size: 18px;
  font-weight: 600;
  text-transform: capitalize;
  transition: 500ms;
  padding: 12px 25px;
  position: relative;
  overflow: hidden;
  border-radius: 30px;
  text-align: center;
}
.travhub-btn::before{
  position: absolute;
  content: '';
  background-color: var(--travhub-black);
  width: 120%;
  height: 0;
  padding-bottom: 120%;
  top: -110%;
  left: -10%;
  border-radius: 50%;
  transform: translate3d(0,68%,0) scale3d(0,0,0);
}
.travhub-btn:hover::before {
  transform: translate3d(0,0,0) scale3d(1,1,1);
  transition: transform 0.4s cubic-bezier(0.1, 0, 0.3, 1);
}
.travhub-btn::after{
  background-color: var(--travhub-black);
  content: '';
  transform: translate3d(0,-100%,0);
  transition: transform 0.4s cubic-bezier(0.1, 0, 0.3, 1);
  transition-duration: 0.4s;
  transition-timing-function: cubic-bezier(0.1, 0, 0.3, 1);
  transition-delay: 0s;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.travhub-btn:hover::after {
  transform: translate3d(0,0,0);
  transition-duration: 0.05s;
  transition-delay: 0.4s;
  transition-timing-function: linear;
}
.travhub-btn span {
  display: block;
  position: relative;
  z-index: 2;
}
.travhub-btn:hover span {
  animation: MoveScaleUpInitial 0.3s forwards, MoveScaleUpEnd 0.3s forwards 0.3s;
}
@keyframes MoveScaleUpInitial {
	to {
		transform: translate3d(0,-105%,0) scale3d(1,2,1);
		opacity: 0;
	}
}

@keyframes MoveScaleUpEnd {
	from {
		transform: translate3d(0,100%,0) scale3d(1,2,1);
		opacity: 0;
	}
	to {
		transform: translate3d(0,0,0);
		opacity: 1;
	}
}
.tabs-box .tabs-content .tab:not(.active-tab) {
  display: none;
}

.bootstrap-select .dropdown-menu {
  padding-top: 0;
  padding-bottom: 0;
  border-radius: 0;
}
.bootstrap-select .dropdown-menu{
  background-color: var(--travhub-white);
  border: 1px solid var(--travhub-border-color);
}
.bootstrap-select .dropdown-item{
  padding: 10px 15px;
  border-bottom: 1px solid var(--travhub-border-color);
}
.bootstrap-select .dropdown-item.active,
.bootstrap-select .dropdown-item:hover {
  background-color: var(--travhub-base);
  color: var(--travhub-white);
  border-color: var(--travhub-base);
}

.ul-list-one {
  margin-bottom: 0;
}
.ul-list-one li {
  position: relative;
  padding-left: 45px;
  font-size: 16px;
  font-weight: 500;
  color: var(--travhub-black);
}
@media (min-width: 481px) {
  .ul-list-one li {
    font-size: 20px;
  }
}
.ul-list-one li::before {
  content: "\e907";
  color: var(--travhub-base);
  font-size: 26px;
  position: absolute;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
  font-family: "azino-icon";
}

.preloader {
  position: fixed;
  background-color: var(--travhub-black);
  background-position: center center;
  background-repeat: no-repeat;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9991;
  display: -webkit-box;
  display: flex;
  -webkit-box-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  align-items: center;
  text-align: center;
}
.preloader__image {
  -webkit-animation-fill-mode: both;
  animation-fill-mode: both;
  -webkit-animation-name: flipInY;
  animation-name: flipInY;
  -webkit-animation-duration: 2s;
  animation-duration: 2s;
  -webkit-animation-iteration-count: infinite;
  animation-iteration-count: infinite;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 60px auto;
  width: 100%;
  height: 100%;
}

/* scroll to top */
.scroll-to-top {
  position: fixed;
  right: 30px;
  bottom: 30px;
  height: 50px;
  width: 50px;
  cursor: pointer;
  display: block;
  border-radius: 50%;
  background-color: transparent;
  z-index: 99;
  opacity: 0;
  padding: 0;
  visibility: hidden;
  transform: translateY(15px);
  -webkit-transition: all 200ms linear;
  transition: all 200ms linear;
}
.scroll-to-top--active{
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.scroll-to-top::after {
  position: absolute;
  content: "\f062";
  font-family: "Font Awesome 5 Free";
  font-weight: 700;
  text-align: center;
  line-height: 50px;
  font-size: 18px;
  color: var(--travhub-base);
  left: 0;
  top: 0;
  height: 100%;
  width: 100%;
  cursor: pointer;
  display: block;
  z-index: 1;
  -webkit-transition: all 200ms linear;
  transition: all 200ms linear;
}
.scroll-to-top::before {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 100%;
  content: '';
  border: 2px solid rgb(var(--travhub-base-rgb), 0.3);
  z-index: -1;
  border-radius: 50%;
}
.scroll-to-top path {
  stroke: var(--travhub-base);
  stroke-width: 4;
  fill: none;
  box-sizing: border-box;
  -webkit-transition: all 200ms linear;
  transition: all 200ms linear;
}

/* post paginations */
.post-pagination {
  margin: 30px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  gap: 10px;
  align-items: center;
}
.post-pagination.text-center {
  justify-content: center;
}
.post-pagination.text-end {
  justify-content: flex-end;
}
.post-pagination--mt0 {
  margin-top: 20px;
}
.post-pagination a {
  display: flex;
  width: 40px;
  height: 40px;
  background-color: transparent;
  align-items: center;
  justify-content: center;
  color: var(--travhub-text);
  font-size: 16px;
  font-weight: 500;
  line-height: 1;
  border-radius: 50%;
  border: 1px solid var(--travhub-border-color);
  transition: all 400ms ease;
}
.post-pagination a i{
  font-size: 13px;
}
.post-pagination a.current, .post-pagination a:hover {
  background-color: var(--travhub-base);
  border-color: var(--travhub-base);
  color: var(--travhub-white);
}
.post-pagination .dots{
  display: flex;
  width: 40px;
  height: 40px;
  background-color: transparent;
  align-items: flex-start;
  justify-content: center;
  color: var(--travhub-text);
  font-size: 16px;
  font-weight: 700;
  line-height: 30px;
  border-radius: 50%;
  border: 1px solid var(--travhub-border-color);
  transition: all 400ms ease;
}
.travhub-owl__carousel--with-shadow .owl-stage-outer {
  overflow: visible;
}
.travhub-owl__carousel--with-shadow .owl-item {
  opacity: 0;
  visibility: hidden;
  transition: opacity 500ms ease, visibility 500ms ease;
}
.travhub-owl__carousel--with-shadow .owl-item.active {
  opacity: 1;
  visibility: visible;
}

.travhub-owl__carousel--basic-nav.owl-carousel .owl-nav {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 40px;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-nav button {
  border: none;
  outline: none;
  width: 70px;
  height: 70px;
  margin: 0;
  padding: 0;
  opacity: 1;
  background-color: transparent;
  border: 1px solid var(--travhub-white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  border-radius: 50%;
  color: var(--travhub-white);
  transition: all 500ms ease;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-nav button:hover {
  color: var(--travhub-white);
  background-color: var(--travhub-base);
  border-color: var(--travhub-base);
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 40px;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-dots .owl-dot {
  width: 10px;
  height: 10px;
  display: block;
  border-radius: 50%;
  background-color: rgba(var(--travhub-base-rgb), 0.2);
  border: none;
  position: relative;
  padding: 0;
  border: none;
  outline: none;
  margin: 0;
  transition: all 300ms ease;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-dots .owl-dot span {
  display: none;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-dots .owl-dot:hover, .travhub-owl__carousel--basic-nav.owl-carousel .owl-dots .owl-dot.active {
  background-color: var(--travhub-base);
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-dots.disabled {
  display: none;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-nav.disabled + .owl-dots {
  margin-top: 40px;
}
.travhub-owl__carousel--basic-nav.owl-carousel .owl-nav.disabled {
  display: none;
}

