  background-size: 100% 1px;
}
.destination-two__item__title a:hover {
  color: var(--travhub-base);
}
.destination-two__item__dec {
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 156%;
  text-transform: capitalize;
  margin-bottom: 0;
  padding-bottom: 0;
  color: var(--travhub-white);
}
.destination-two__item__btn a {
