  width: 43px;
  height: 43px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.destination-two__item__btn a span {
  line-height: 0 !important;
}
.destination-two__item__btn a::before {
  display: none;
}
.destination-two__element-one {
  position: absolute;
  top: 30%;
  left: 0;
  transform: translateY(-50%);
  @media (max-width: 1199px) {
    display: none;
  }
}
.destination-two__element-one img {
  animation: movebounce2 4s linear infinite;
}
.destination-two__element-two {
  position: absolute;
  top: 30%;
  right: 0;
  transform: translateY(-50%);
  @media (max-width: 1199px) {
    display: none;
  }
}
.destination-two__element-two img {
  animation: movebounce2 4s linear infinite;
}

.destination-three {
  position: relative;
  z-index: 1;
  padding-top: 120px;
  @media (max-width: 767px) {
    padding-top: 80px;
  }
}
.destination-three__shape{
  position: absolute;
  left: 0;
  bottom: 50px;
  width: 100%;

  @media (max-width: 1399px){
    display: none;
  }
}
.destination-three__shape img{
  max-width: 100%;
}
.destination-three__image {
  background: #D9D9D9;
  border-radius: 0px 100px;
  transform: matrix(-1, 0, 0, 1, 0, 0);
  overflow: hidden;
  position: relative;
  z-index: 1;
  transition: all 0.4s ease-in-out;
}
.destination-three__image img {
  -o-object-fit: cover;
     object-fit: cover;
  width: 100%;
  transition: all 0.4s ease-in-out;
  transform: scale(1);
}
.destination-three__image::after {
  content: "";
  width: 100%;
  height: 50%;
  position: absolute;
  bottom: 0;
  left: 0;
  visibility: visible;
  transition: all 0.4s ease-in-out;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, #000000 100%);
}
.destination-three__image::before {
  content: "";
  width: 100%;
  height: 100%;
  z-index: 1;
  position: absolute;
  bottom: 0;
  left: 0;
  transition: all 0.4s ease-in-out;
  visibility: visible;
  opacity: 0;
  background-color: rgba(0, 0, 0, 0.6);
}
.destination-three__item {
  position: relative;
  z-index: 1;
}
.destination-three__item__content {
  position: absolute;
  bottom: 42px;
  text-align: center;
  left: 40%;
  transform: translateX(-32%);
  z-index: 1;
  transition: all 0.4s ease-in-out;
}
.destination-three__item__title {
  margin: 0;
  font-style: normal;
  font-weight: 600;
  font-size: 24px;
  line-height: 133%;
  text-align: center;
  text-transform: capitalize;
  transition: all 0.4s ease-in-out;
  color: var(--travhub-white);
  margin-bottom: -54px;
}
.destination-three__item__title a {
  color: inherit;
  background: linear-gradient(to right, currentcolor 0%, currentcolor 100%) 0px 95%/0px 1px no-repeat;
  transition: all 500ms ease;
}
.destination-three__item__title a:hover{
  background-size: 100% 1px;
  color: var(--travhub-base);
}
.destination-three__item__text {
  margin: 0;
  font-family: var(--travhub-font);
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 150%;
  text-align: center;
  text-transform: capitalize;
  color: var(--travhub-white);
  max-width: 200px;
  width: 100%;
  margin-left: auto;
  margin-right: auto;
  transform: rotateY(90deg);
  transition: all 0.4s ease-in-out;
  margin-bottom: 16px;
}
.destination-three__item__btn {
  text-align: center;
  font-style: normal;
  font-weight: 600;
  font-size: 14px;
  line-height: 179%;
  color: var(--travhub-white);
  border-radius: 20px;
  border: 1px solid var(--travhub-white);
  padding: 6px 10px;
  transition: all 0.4s ease-in-out;
}
.destination-three__item__btn:hover {
  background-color: var(--travhub-base);
  border-color: var(--travhub-base);
}
.destination-three__item__link {
  position: absolute;
  bottom: 0px;
  left: 0;
  z-index: 1;
  width: 102px;
  height: 102px;
  border-radius: 50%;
  border: 9px solid var(--travhub-white);
  background-color: var(--travhub-base);
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transition: all 0.4s ease-in-out;
}
.destination-three__item__link:hover {
  background-color: var(--travhub-black);
  border-color: var(--travhub-base);
}
.destination-three__item__link a {
  color: inherit;
  font-size: 42px;
  color: var(--travhub-white);
}
.destination-three__item:hover .destination-three__image::after {
  visibility: hidden;
  opacity: 0;
}
.destination-three__item:hover .destination-three__image::before {
  visibility: visible;
  opacity: 1;
}
.destination-three__item:hover .destination-three__item__content {
  bottom: 50%;
  transform: translate(-32%, 50%);
}
.destination-three__item:hover .destination-three__item__text {
  transform: rotateY(0deg);
}
.destination-three__item:hover .destination-three__item__title {
  margin-bottom: 5px;
}
.destination-three__item:hover .destination-three__image {
  border-radius: 100px 0px;
}
.destination-three__item:hover .destination-three__image img {
  transform: scale(1.1);
}
.destination-three__item:hover .destination-three__item__link {
  visibility: visible;
  opacity: 1;
}

