}
.destination-details .gutter-x-16 .col-xl-3{
  width: 19.2%;

  @media (max-width: 574px){
    width: 50%;
  }
}
.destination-details .gutter-x-16 .col-xl-4{
  width: 39.8%;

  @media (max-width: 574px){
    width: 50%;
  }
}
.destination-details .mt25{
  margin-top: 25px;
}
.destination-details__content{
  position: relative;
}
.destination-details__title{
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 16px;
}
.destination-details__text{
  font-size: 15px;
  line-height: 26px;
