}
.destination-details__pricing::after{
  content: "";
  width: 100%;
  height: 0;
  position: absolute;
  left: 0;
  top: auto;
  bottom: 0;
  transition: height 0.5s cubic-bezier(0.25, 0.8, 0.25, 1) 0.2s;
  background-color: var(--travhub-base);
  z-index: -1;
}
.destination-details__pricing:hover:after{
  height: 100%;
  top: 0;
  bottom: auto;
}
.destination-details__pricing__sub-title{
  font-size: 18px;
  line-height: 1;
  margin: 0 0 9px;
  transition: all 0.3s;
}
.destination-details__pricing:hover .destination-details__pricing__sub-title{
  color: var(--travhub-white);
}
.destination-details__pricing__title{
  font-size: 35px;
  font-weight: 500;
  letter-spacing: -1.07px;
  line-height: 1;
  margin: 0 0 13px;
  transition: all 0.3s;
}
.destination-details__pricing:hover .destination-details__pricing__title{
  color: var(--travhub-white);
}
.destination-details__pricing__text{
  font-size: 14px;
  letter-spacing: -0.39px;
  line-height: 21px;
  margin: 0 0 28px;
  transition: all 0.3s;
}
.destination-details__pricing:hover .destination-details__pricing__text{
  color: var(--travhub-white);
}
.destination-details__pricing .travhub-btn{
