}
.destination-details__pricing:hover .travhub-btn span {
  animation: MoveScaleUpInitial 0.3s forwards, MoveScaleUpEnd 0.3s forwards 0.3s;
}
.destination-details__pricing:hover .travhub-btn::before{
  background-color: var(--travhub-white);
  transform: translate3d(0,0,0) scale3d(1,1,1);
  transition: transform 0.4s cubic-bezier(0.1, 0, 0.3, 1);
}
.destination-details__pricing:hover .travhub-btn::after{
  background-color: var(--travhub-white);
  transform: translate3d(0,0,0);
  transition-duration: 0.05s;
  transition-delay: 0.4s;
  transition-timing-function: linear;
}
.destination-details__pricing__list-title{
  font-size: 15px;
  font-weight: 500;
  color: var(--travhub-black);
  text-align: left;
  transition: all 0.3s;
  margin: 19px 0 11px;
}
.destination-details__pricing:hover .destination-details__pricing__list-title{
  color: var(--travhub-white);
}
.destination-details__pricing__list{
  margin: 0;
  padding: 0;
  list-style: none;
  text-align: left;
  margin-right: -10px;
}
.destination-details__pricing__list li{
  position: relative;
  font-size: 15px;
  padding-left: 17px;
  line-height: 21px;
  color: var(--travhub-text);
  margin-top: 10px;
  transition: all 0.3s;
}
.destination-details__pricing:hover .destination-details__pricing__list li{
  color: var(--travhub-white);
}
.destination-details__pricing__list li::before{
  position: absolute;
  left: 0;
  top: 6px;
  content: '';
  width: 7px;
  height: 7px;
  background-color: var(--travhub-base);
  border-radius: 50%;
  transition: all 0.3s;
}
.destination-details__pricing:hover .destination-details__pricing__list li::before{
  background-color: var(--travhub-white);
}

