  top: 30px;
  left: 30px;
  font-family: var(--travhub-font);
  font-style: normal;
  font-weight: 600;
  font-size: 14px;
  line-height: 16px;
  text-align: center;
  background-color: #F5B715;
  padding: 5px 10px;
  border-radius: 2px;
  text-transform: capitalize;
  color: var(--travhub-black);
}
.tours-two__btns {
  display: flex;
  align-items: center;
  gap: 10px;
  position: absolute;
  bottom: 76px;
  right: 20px;
  transform: translateY(120px);
  transition: all 0.5s ease-in-out;
}
.tours-two__btns a {
  width: 35px;
  height: 35px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--travhub-white);
  font-size: 18px;
  line-height: 1;
  color: var(--travhub-text);
}
.tours-two__btns a i{
  height: 18px;
}
.tours-two__btns a:hover {
  background-color: var(--travhub-base);
  color: var(--travhub-white);
}
.tours-two__content {
  padding: 17px 30px 24px;
}
@media (max-width: 490px) {
  .tours-two__content {
    padding: 25px 30px 25px;
  }
}
.tours-two__feature {
  background-color: var(--travhub-base);
  font-weight: 500;
  font-size: 14px;
  line-height: 16px;
  text-transform: capitalize;
  color: var(--travhub-white);
  display: inline-block;
  padding: 4px 9px;
  border-radius: 4px;
  margin-bottom: 12px;
}
.tours-two__price {
  font-family: var(--travhub-heading-font);
  font-style: normal;
  font-weight: 600;
  font-size: 32px;
  line-height: 32px;
  text-transform: capitalize;
  color: #282828;
  margin-bottom: 6px;
}
.tours-two__price span {
  font-size: 24px;
}
.tours-two__title {
  margin: 0;
  font-style: normal;
  font-weight: 500;
  font-size: 24px;
  text-transform: capitalize;
  line-height: 133%;
  color: #282828;
  margin-bottom: 15px;
}
.tours-two__title a {
  color: inherit;
  background: linear-gradient(to right, currentcolor 0%, currentcolor 100%) 0px 95%/0px 1px no-repeat;
}
.tours-two__title a:hover {
  color: var(--travhub-base);
  background-size: 100% 1px;
}
.tours-two__meta {
  display: flex;
  align-items: center;
  justify-content: start;
  gap: 17px;
  margin-bottom: -2px;
}
.tours-two__meta a {
  font-family: var(--travhub-font);
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 156%;
  text-transform: capitalize;
  color: #282828;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all 0.4s ease-in-out;
}
.tours-two__meta a span {
  font-family: var(--travhub-font);
  font-style: normal;
  font-weight: 600;
  font-size: 14px;
  line-height: 169%;
  display: inline-block;
  background-color: var(--travhub-base);
  color: var(--travhub-white);
  padding: 0 4px;
  border-radius: 4px;
}
.tours-two__meta a:hover {
  color: var(--travhub-base);
}
