/*--------------------------------------------------------------
# Tours Detils
--------------------------------------------------------------*/
.tours-details{
  position: relative;
  padding: 120px 0px;

  @media (max-width: 767px) {
    padding: 80px 0px;
  }
}
.tours-details__image{
  position: relative;
  margin: 0 0 33px;
}
.tours-details__image img{
  width: 100%;
  height: auto;
  border-radius: 12px;
}
.tours-details__content{
  position: relative;
}
.tours-details__title{
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 14px;
}
.tours-details .mt35{
  margin-top: 35px;
}
.tours-details__text{
  font-size: 15px;
  line-height: 26px;
  margin: 0 0 10px;
}
.tours-details__list{
  margin: 18px 0 0;
  padding: 0;
  list-style: none;
}
.tours-details__list li{
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 16px;
  line-height: 28px;
  margin: 0 0 12px;
}
.tours-details__list li i{
  width: 18px;
  height: 18px;
  background-color: var(--travhub-base);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 8px;
  flex-shrink: 0;
  color: var(--travhub-white);
}
.tours-details .row.gutter-x-24{
  --bs-gutter-x: 24px;
  margin-top: 33px;
}
.tours-details__gallery{
  position: relative;
  margin-bottom: 13px;
}
.tours-details__gallery img{
  width: 100%;
  height: auto;
  border-radius: 12px;
}

.tours-details__accordion {
  position: relative;
  margin: 0 0 45px;
}
.tours-details__accordion .accrodion {
  position: relative;
  padding: 40px 0;
}
.tours-details__accordion .accrodion::after{
  position: absolute;
  left: 50px;
  bottom: 0;
  width: calc(100% - 50px);
  height: 1px;
  background-color: var(--travhub-border-color);
  content: '';
}
.tours-details__accordion .accrodion-title {
  padding: 0;
  padding-right: 60px;
  cursor: pointer;
  transition: all 500ms ease;
}
.tours-details__accordion .accrodion-title h4 {
  font-weight: 500;
  color: var(--travhub-black);
  font-size: 20px;
  margin: 0;
  transition: all 500ms ease;
  position: relative;
  display: flex;
  align-items: center;
}
.tours-details__accordion .accrodion-title h4 i{
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 50%;
  color: var(--travhub-base);
  background-color: rgba(var(--travhub-base-rgb), 0.12);
  border-radius: 50%;
  font-size: 14px;
  margin-right: 12px;
}
.tours-details__accordion .accrodion-title__icon {
  width: 20px;
  height: 20px;
  background-color: var(--travhub-black);
  border-radius: 50%;
  position: absolute;
  top: 50%;
  right: -40px;
  transform: translateY(-50%);
  transition: all 500ms ease;
}
.tours-details__accordion .accrodion-title__icon::after, .tours-details__accordion .accrodion-title__icon::before {
  width: 2px;
  height: 10px;
  position: absolute;
  background-color: var(--travhub-white);
  top: 50%;
  left: 50%;
  content: "";
  transform: translate(-50%, -50%);
  transition: all 500ms ease;
  z-index: 2;
}
.tours-details__accordion .accrodion-title__icon::after {
  width: 10px;
  height: 2px;
}
.tours-details__accordion .active .accrodion-title__icon::after, .tours-details__accordion .active .accrodion-title__icon::before {
  opacity: 0;
}
.tours-details__accordion .active .accrodion-title__icon::after {
  opacity: 1;
}
.tours-details__accordion .accrodion-content .inner {
  padding: 10px 10px 0 50px;
}
.tours-details__accordion .accrodion-content p {
  margin: 0;
  font-size: 15px;
  line-height: 26px;
}

.tours-details__map{
  position: relative;
  overflow: hidden;
  background-color: var(--travhub-gray);
  margin: 30px 0 60px;
}
.tours-details__map iframe{
  position: relative;
  display: block;
  border: none;
  height: 476px;
  width: 100%;
  mix-blend-mode: luminosity;

  @media (max-width: 767px){
    height: 400px;
  }
}
.tours-details__rel-title{
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 34px;
}

.tours-details__booking{
  position: relative;
  border: 1px solid rgba(var(--travhub-black-rgb), 0.1);
  background-color: #FAFAFA;
  border-radius: 8px;
  padding: 31px 22px 32px;

  @media (min-width: 1400px) {
    margin-left: 20px;
  }
}
.tours-details__booking__title{
  text-transform: capitalize;
  line-height: 1em;
  font-size: 20px;
  font-weight: 600;
  margin-top: -2px;
  margin-bottom: 17px;
}
.tours-details__booking__title::before{
  position: relative;
  display: inline-block;
  width: 4px;
  height: 22px;
  content: '';
  margin-right: 14px;
  top: 4px;
  background-color: var(--travhub-base);
}
.tours-details__booking__list{
  margin: 0;
  padding: 0;
  list-style: none;
}
.tours-details__booking__list li{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 20px;
  line-height: 24px;
  font-weight: 600;
  color: var(--travhub-black);
  border-bottom: 1px solid rgba(var(--travhub-black-rgb), 0.1);
  padding: 0 0 14px;
  margin: 0 0 17px;
}
.tours-details__booking__list li:first-child .tours-details__booking__list__left span{
  margin: 0 0;
  font-family: var(--travhub-font);
}
.tours-details__booking__list li:first-child .tours-details__booking__list__left{
  font-size: 20px;
  font-weight: 600;
  font-family: var(--travhub-heading-font);
}
.tours-details__booking__list li:last-child{
  border: none;
  padding-bottom: 0;
}
.tours-details__booking__list li:last-child .tours-details__booking__list__left span{
  margin: 12px 0 0;
}
.tours-details__booking__list__left{
  margin: 0;
  font-size: 16px;
  line-height: 24px;
  font-weight: 700;
  display: flex;
  flex-direction: column;
  font-family: var(--travhub-font);
}
.tours-details__booking__list__left span{
  display: block;
  font-size: 16px;
  font-weight: 400;
  font-family: var(--travhub-font);
  color: var(--travhub-text);
  margin-top: 1px;
}
.tours-details__booking__list__control{
  width: 117px;
  height: 39px;
  background-color: var(--travhub-white);
  border-radius: 100px;
  border: 1px solid rgba(var(--travhub-black-rgb), 0.04);
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  padding: 0 9px;
}
.tours-details__booking__list__control input[type="number"]{
  display: block;
  width: 100%;
  background-color: transparent;
  font-size: 16px;
  font-weight: 500;
  height: 39px;
  font-family: var(--travhub-heading-font);
  border: none;
  outline: none;
  text-align: center;
  padding: 0 15px;
}
input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}
.tours-details__booking__list__control button{
  width: 24px;
  height: 24px;
  background-color: var(--travhub-text);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 14px;
  color: var(--travhub-white);
  border: none;
  outline: none;
  padding: 0;
  margin: 0;
  transition: all 0.5s;
  flex-shrink: 0;
}
.tours-details__booking__list__control button:hover{
  background-color: var(--travhub-base);
}
.tours-details__booking .form-one .travhub-btn{
  width: 100%;
  border-radius: 30px;
  padding: 12px 20px;
  margin-top: 38px;
}
.tours-details__booking__check-box{
  position: relative;
  margin-top: 10px;
}
.tours-details__booking__check-box input[type="checkbox"] {
  display: none;
}
.tours-details__booking__check-box label {
  position: relative;
  display: inline-block;
  padding-left: 30px;
  margin-right: 0px;
  margin-bottom: 0;
  font-size: 16px;
  font-family: var(--travhub-heading-font);
  line-height: 24px;
  font-weight: 400;
  text-transform: none;
  cursor: pointer;
}
.tours-details__booking__check-box input[type="checkbox"] + label span {
  position: absolute;
  top: 5px;
  left: 0px;
  width: 16px;
  height: 16px;
  border-radius: 3px;
  vertical-align: middle;
  background: transparent;
  cursor: pointer;
  transition: 300ms;
  border: 1px solid var(--travhub-black3);
}
.tours-details__booking__check-box label span::before {
  position: absolute;
  top: 2px;
  left: 3px;
  display: block;
  border-bottom: 2px solid var(--travhub-white);
  border-right: 2px solid var(--travhub-white);
  content: "";
  width: 5px;
  height: 8px;
  pointer-events: none;
  transform-origin: 66% 66% 0px;
  transform: rotate(45deg);
  transition: 0.15s ease-in-out;
  opacity: 0;
}
.tours-details__booking__check-box input[type="checkbox"]:checked + label span {
  border-color: var(--travhub-base);
  background-color: var(--travhub-base);
}
.tours-details__booking__check-box input[type="checkbox"]:checked + label span::before {
  opacity: 1;

}

/*--------------------------------------------------------------
# Pricing Page
--------------------------------------------------------------*/
.pricing-one{
  position: relative;
  padding: 120px 0px;

  @media (max-width: 767px) {
    padding: 80px 0px;
  }
}
.pricing-one__pricing{
  position: relative;
  z-index: 2;
  background-color: #F1F4FA;
  border: 1px solid var(--travhub-border-color);
  border-radius: 16px;
  overflow: hidden;
  padding: 36px 35px 38px;
  text-align: center;
  transition: all 0.5s;

  @media (min-width: 1200px) and (max-width: 1399px){
    padding: 36px 27px 38px;
  }
}
.pricing-one__pricing:hover{
  border-color: var(--travhub-base);
}
.pricing-one__pricing::after{
  content: "";
  width: 100%;
  height: 0;
  position: absolute;
  left: 0;
  top: auto;
  bottom: 0;
  transition: height 0.5s cubic-bezier(0.25, 0.8, 0.25, 1) 0.2s;
  background-color: var(--travhub-base);
  z-index: -1;
}
.pricing-one__pricing:hover:after{
  height: 100%;
  top: 0;
  bottom: auto;
}
.pricing-one__pricing__sub-title{
  font-size: 20px;
  line-height: 1;
  margin: 0 0 12px;
  transition: all 0.3s;
}
.pricing-one__pricing:hover .pricing-one__pricing__sub-title{
  color: var(--travhub-white);
}
.pricing-one__pricing__title{
  font-size: 40px;
  font-weight: 500;
  letter-spacing: -1.21px;
  line-height: 1;
  margin: 0 0 13px;
  transition: all 0.3s;
}
.pricing-one__pricing:hover .pricing-one__pricing__title{
  color: var(--travhub-white);
}
.pricing-one__pricing__text{
  font-size: 16px;
  letter-spacing: -0.43px;
  line-height: 24px;
  margin: 0 0 31px;
  transition: all 0.3s;
}
.pricing-one__pricing:hover .pricing-one__pricing__text{
  color: var(--travhub-white);
}
.pricing-one__pricing .travhub-btn{
  width: 100%;
  font-weight: 400;
  border-radius: 60px;
  transition: all 0.3s;
  padding: 7.2px 25px;
}
.pricing-one__pricing:hover .travhub-btn{
  color: var(--travhub-base);
}
.pricing-one__pricing:hover .travhub-btn span {
  animation: MoveScaleUpInitial 0.3s forwards, MoveScaleUpEnd 0.3s forwards 0.3s;
}
.pricing-one__pricing:hover .travhub-btn::before{
  background-color: var(--travhub-white);
  transform: translate3d(0,0,0) scale3d(1,1,1);
  transition: transform 0.4s cubic-bezier(0.1, 0, 0.3, 1);
}
.pricing-one__pricing:hover .travhub-btn::after{
  background-color: var(--travhub-white);
  transform: translate3d(0,0,0);
  transition-duration: 0.05s;
  transition-delay: 0.4s;
  transition-timing-function: linear;
}
.pricing-one__pricing__list-title{
  font-size: 16px;
  font-weight: 500;
  color: var(--travhub-black);
  text-align: left;
  transition: all 0.3s;
  margin: 22px 0 13px;
}
.pricing-one__pricing:hover .pricing-one__pricing__list-title{
  color: var(--travhub-white);
}
.pricing-one__pricing__list{
  margin: 0;
  padding: 0;
  list-style: none;
  text-align: left;
  margin-right: -10px;
}
.pricing-one__pricing__list li{
  position: relative;
  font-size: 16px;
  padding-left: 17px;
  line-height: 24px;
  color: var(--travhub-text);
  margin-top: 12px;
  transition: all 0.3s;
}
.pricing-one__pricing:hover .pricing-one__pricing__list li{
  color: var(--travhub-white);
}
.pricing-one__pricing__list li::before{
  position: absolute;
  left: 0;
  top: 9px;
  content: '';
  width: 8px;
  height: 8px;
  background-color: var(--travhub-base);
  border-radius: 50%;
  transition: all 0.3s;
}
.pricing-one__pricing:hover .pricing-one__pricing__list li::before{
  background-color: var(--travhub-white);
}

.pricing-info{
  position: relative;
  padding: 0 0 120px;

  @media (max-width: 767px) {
    padding: 0 0px 80px;
  }
}
.pricing-info__item{
  position: relative;
  border: 1px solid var(--travhub-border-color);
  border-radius: 15px;
  padding: 60px 30px;
  z-index: 1;
  transition: all 0.5s;
}
