/*--------------------------------------------------------------
# Blog Page
--------------------------------------------------------------*/
.blog-grid{
  position: relative;
  padding: 120px 0;

  @media (max-width: 767px){
    padding: 80px 0;
  }
}
.blog-list{
  position: relative;
  padding: 120px 0;

  @media (max-width: 767px){
    padding: 80px 0;
  }
}
.blog-list .post-pagination{
  margin-top: 0;
}
.blog-list__item{
  position: relative;
}
.blog-list__item__thumb{
  position: relative;
  overflow: hidden;
  margin: 0 0 26px;
  border-radius: 10px;
}
.blog-list__item__thumb img{
  transition: 0.5s;
  background-size: cover;
  width: 100%;
  height: auto;
}
.blog-list__item__thumb img:nth-child(1) {
  transform: translatex(50%) scalex(2);
  opacity: 0;
  filter: blur(10px);
}
.blog-list__item:hover .blog-list__item__thumb img:nth-child(1){
  transform: translatex(0) scalex(1);
  opacity: 1;
  filter: blur(0);
}
.blog-list__item__thumb img:nth-child(2) {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  object-fit: cover;
}
.blog-list__item:hover .blog-list__item__thumb img:nth-child(2){
  transform: translatex(-50%) scalex(2);
  opacity: 0;
  filter: blur(10px);
}
.blog-list__item__date{
  position: absolute;
  left: 25px;
  top: 25px;
  width: 60px;
  height: 71px;
  background-color: var(--travhub-base);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  font-size: 28px;
  text-transform: uppercase;
  color: var(--travhub-white);
  font-weight: 800;
  font-family: var(--travhub-heading-font);
}
.blog-list__item__date span{
  display: block;
  font-size: 16px;
  font-family: var(--travhub-font);
  color: var(--travhub-black);
  width: 100%;
  line-height: 23px;
  background-color: var(--travhub-white);
  text-align: center;
}
.blog-list__item__content{
  position: relative;
}
.blog-list__item__meta {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 0 0 3px;
  padding: 0;
  list-style: none;
}
.blog-list__item__meta li{
  color: var(--travhub-text);
  text-transform: capitalize;
  font-size: 15px;
  display: flex;
  align-items: center;
  gap: 10px;
  position: relative;
}
.blog-list__item__meta li a{
  color: inherit;
}
.blog-list__item__meta li a:hover{
  color: var(--travhub-base);
}
.blog-list__item__meta li:not(:first-of-type)::before {
  content: "";
  width: 1px;
  height: 10px;
  background-color: var(--travhub-text2);
  position: relative;
  display: inline-block;
  margin: 0 8px 0 14px;
}
.blog-list__item__meta li i{
  position: relative;
  top: -1px;
  color: var(--travhub-base);
  display: inline-block;
}
.blog-list__item__title {
  font-size: 28px;
  font-weight: 700;
  line-height: 36px;
  margin: 0 0 17px;
}
.blog-list__item__title a{
  color: inherit;
  background: linear-gradient(to right, currentcolor 0%, currentcolor 100%) 0px 95%/0px 1px no-repeat;
  transition: all 500ms ease;
}
.blog-list__item__title a:hover{
  background-size: 100% 1px;
  color: var(--travhub-base);
}
.blog-list__item__text{
  font-size: 18px;
  line-height: 26px;
  margin: 0 0 24px;
}
.blog-list__item .travhub-btn{
  font-size: 16px;
