.login__form__btns a{
  border: 1px solid var(--travhub-border-color);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 500;
  text-transform: capitalize;
  color: var(--travhub-text);
  gap: 8px;
  padding: 4px 19px;

  @media (min-width: 992px) and (max-width: 1199px){
    gap: 5px;
    padding: 4px 10px;
  }
}
.login__form__btns a:hover{
  border-color: var(--travhub-base);
  color: var(--travhub-base);
}
.login__form__others{
  position: relative;
  max-width: 400px;
  margin: 27px auto 16px;
  font-size: 12px;
  text-transform: uppercase;
  text-align: center;
  position: relative;
}
.login__form__others span{
  position: relative;
  display: inline-block;
  background-color: var(--travhub-white);
  padding: 0 15px;
}
.login__form__others::after{
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  width: 100%;
  height: 1px;
  background-color: var(--travhub-border-color);
  content: '';
  z-index: -1;
}

.login__form__input{
  position: relative;
  display: block;
  margin-bottom: 16px;
}
.login__form__input label{
  display: block;
  font-size: 16px;
  cursor: pointer;
  font-weight: 500;
  color: var(--travhub-black);
  margin: 0 0 5px;
}
.login__form__input input{
  height: 48px;
  width: 100%;
  border: 1px solid var(--travhub-border-color);
  background-color: transparent;
  border-radius: 8px;
  padding-left: 20px;
  padding-right: 20px;
  outline: none;
  font-size: 16px;
  color: rgba(var(--travhub-text-rgb), 0.6);
  display: block;
  font-weight: 400;
  transition: all 400ms ease;

  &:focus{
    color: rgba(var(--travhub-text-rgb), 1);
  }
}


.login__form__check{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 18px 0 25px;
}
.login__form__check__box{
  position: relative;
}
.login__form__check__box input[type="checkbox"] {
  display: none;
}
.login__form__check__box label{
  position: relative;
  display: inline-block;
  padding-left: 26px;
  margin-right: 0px;
  margin-bottom: 0;
  font-size: 14px;
  line-height: 22px;
  font-weight: 400;
  text-transform: none;
  cursor: pointer;
}
.login__form__check__box input[type="checkbox"] + label span {
  position: absolute;
  top: 2px;
  left: 0;
  width: 16px;
  height: 16px;
  border-radius: 5px;
  vertical-align: middle;
  background: transparent;
  cursor: pointer;
  -webkit-transition: all 300ms ease;
  -moz-transition: all 300ms ease;
  -ms-transition: all 300ms ease;
  -o-transition: all 300ms ease;
  transition: all 300ms ease;
  border: 1px solid var(--travhub-border-color);
}
.login__form__check__box label span::before {
  position: absolute;
  top: 2px;
  left: 3px;
  display: block;
  border-bottom: 2px solid var(--travhub-white);
  border-right: 2px solid var(--travhub-white);
  content: "";
  width: 5px;
  height: 8px;
  pointer-events: none;
  -webkit-transform-origin: 66% 66%;
  -ms-transform-origin: 66% 66%;
  transform-origin: 66% 66%;
  -webkit-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  transform: rotate(45deg);
  -webkit-transition: all 0.15s ease-in-out;
  transition: all 0.15s ease-in-out;
  opacity: 0;
}
.login__form__check__box input[type="checkbox"]:checked + label span{
  border-color: var(--travhub-base);
  background-color: var(--travhub-base);
}
.login__form__check__box input[type="checkbox"]:checked + label span::before {
  opacity: 1;
}
 


.login__form__check__forgot-password{
  position: relative;
  margin: 0;
  font-size: 14px;
}
.login__form__check__forgot-password a{
  color: inherit;
  background: linear-gradient(to right, currentcolor 0%, currentcolor 100%) 0px 95%/0px 1px no-repeat;
  transition: all 500ms ease;
}
.login__form__check__forgot-password a:hover{
  background-size: 100% 1px;
  color: var(--travhub-base);
}


.login-page__form-btn-box{
  position: relative;
  text-align: center;
}
.login-page__form-btn-box .travhub-btn{
  width: 100%;
  text-align: center;
  border-radius: 8px;
  padding: 7.2px 25px;
}
.login-page__form-btn-box__register-text{
  font-size: 14px;
  margin: 17px 0 0;
}
.login-page__form-btn-box__register-text a{
  color: var(--travhub-base);
  background: linear-gradient(to right, currentcolor 0%, currentcolor 100%) 0px 95%/0px 1px no-repeat;
  transition: all 500ms ease;
}
.login-page__form-btn-box__register-text a:hover{
  background-size: 100% 1px;
}

